def get_items():
    from scripts.generators import gen_lugar_extra as gle
    return [bc.make_item(*x) for x in RAW_LUGAR] + gle.get_extra_items()

def get_new_items():
    existing = bc.get_existing_names_for_theme('Lugar')
    all_cand = get_items()
    
    seen = set()
    unique_new = []
    for x in all_cand:
        name = bc.get_item_name(x)
        norm = bc.normalize_name(name)
        if norm not in existing and norm not in seen:
            seen.add(norm)
            unique_new.append(x)
    return unique_new
